ui_drafts.plugin:
{
  "schema_version": "spobs-plugin/1",
  "id": "local.creative-tools",
  "name": "Creative tools",
  "version": "1.0.0",
  "description": "An editable example plugin. Scale numbers, generate samples, and create your own safe JSON tools.",
  "nodes": [
    {
      "id": "scale",
      "title": "Scale value",
      "category": "Custom",
      "description": "Multiply a numeric input by an editable factor.",
      "inputs": [
        {
          "name": "value",
          "type": "number",
          "required": true,
          "default": 21
        }
      ],
      "outputs": [
        {
          "name": "value",
          "type": "number"
        }
      ],
      "parameters": [
        {
          "name": "factor",
          "type": "number",
          "default": 2
        }
      ],
      "code": "console.log(\"Scaling\", inputs.value, \"by\", params.factor);\nreturn {value: inputs.value * params.factor};"
    },
    {
      "id": "samples",
      "title": "Generate sample data",
      "category": "Custom",
      "description": "Generate a portable dataset using a simple line.",
      "inputs": [],
      "outputs": [
        {
          "name": "dataset",
          "type": "dataset"
        }
      ],
      "parameters": [
        {
          "name": "slope",
          "type": "number",
          "default": 2
        },
        {
          "name": "count",
          "type": "integer",
          "default": 20,
          "min": 2,
          "max": 10000
        }
      ],
      "code": "const xs = Array.from({length: params.count}, (_, i) => -1 + 2 * i / (params.count - 1));\nreturn {dataset: {inputs: xs, targets: xs.map(x => x * params.slope), batch_size: Math.min(32, params.count)}};"
    }
  ],
  "panels": [
    {
      "id": "scale-controls",
      "title": "Scale controls",
      "description": "Create an Object node from these values and wire it into a script.",
      "fields": [
        {
          "name": "value",
          "type": "number",
          "default": 21
        },
        {
          "name": "factor",
          "type": "number",
          "default": 2
        }
      ]
    }
  ]
}
